class Solution {
public:
    int maximumPoints(vector<vector<int>>& edges, vector<int>& coins, int k) {
        int n = coins.size();
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        vector<vector<int>> memo(n, vector<int>(15, -1));
        function<int(int, int, int)> dfs = [&](int u, int p, int c) -> int {
            c = min(c, 14);
            if (memo[u][c] != -1) return memo[u][c];
            int val = coins[u] >> c;
            int res1 = val - k;
            for (int v : adj[u]) {
                if (v != p) res1 += dfs(v, u, c);
            }
            int res2 = val / 2;
            for (int v : adj[u]) {
                if (v != p) res2 += dfs(v, u, c + 1);
            }
            return memo[u][c] = max(res1, res2);
        };
        return dfs(0, -1, 0);
    }
};

class Solution {
    int[][] memo;
    List<Integer>[] adj;
    int[] coins;
    int k;
    int dfs(int u, int p, int c) {
        c = Math.min(c, 14);
        if (memo[u][c] != -1) return memo[u][c];
        int val = coins[u] >> c;
        int res1 = val - k;
        for (int v : adj[u]) {
            if (v != p) res1 += dfs(v, u, c);
        }
        int res2 = val / 2;
        for (int v : adj[u]) {
            if (v != p) res2 += dfs(v, u, c + 1);
        }
        return memo[u][c] = Math.max(res1, res2);
    }
    public int maximumPoints(int[][] edges, int[] coins, int k) {
        int n = coins.length;
        this.coins = coins;
        this.k = k;
        adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        memo = new int[n][15];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dfs(0, -1, 0);
    }
}

/**
 * @param {number[][]} edges
 * @param {number[]} coins
 * @param {number} k
 * @return {number}
 */
var maximumPoints = function(edges, coins, k) {
    const n = coins.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const memo = Array.from({ length: n }, () => new Int32Array(15).fill(-1));
    function dfs(u, p, c) {
        c = Math.min(c, 14);
        if (memo[u][c] !== -1) return memo[u][c];
        const val = coins[u] >> c;
        let res1 = val - k;
        for (const v of adj[u]) {
            if (v !== p) res1 += dfs(v, u, c);
        }
        let res2 = Math.floor(val / 2);
        for (const v of adj[u]) {
            if (v !== p) res2 += dfs(v, u, c + 1);
        }
        const ans = Math.max(res1, res2);
        memo[u][c] = ans;
        return ans;
    }
    return dfs(0, -1, 0);
};
